#include "TapPanel.hpp"
#import <AppKit/AppKit.h>
namespace tap {void copyPanelText(const std::string&text){@autoreleasepool{NSString *value=[[NSString alloc] initWithBytes:text.data() length:text.size() encoding:NSUTF8StringEncoding];if(!value)return;NSPasteboard *clipboard=[NSPasteboard generalPasteboard];[clipboard clearContents];[clipboard setString:value forType:NSPasteboardTypeString];}}}

namespace tap {void showPanelAbout(){@autoreleasepool{NSAlert *alert=[[NSAlert alloc] init];alert.messageText=@"GTap — Ghetto Scopez signal tap";alert.informativeText=@"Made by Vidar Andersen. Free and open source.\nFor more: https://vidarandersen.com/dmz/ghettoscopez\n\nSends this node's full-resolution float32 RGB pixels to Ghetto Scopez in a browser on any device on your network. The image passes through unchanged.\n\nSOURCE / WORKING-SPACE TAP\nChoose Source / working-space RGB in Input to measure float32 RGB exactly at this node without a colour transform. Negative and above-one values are retained. Primaries and transfer remain unknown; this mode does not infer your project colour space. Weighted RGB and difference views use fixed BT.709 analysis coefficients, not calibrated working-space luma/chroma. Display targets and the skin-tone guide are hidden. RGB preview/trace colours are raw visualisations, not colour-managed previews.\n\nWHERE TO PLACE IT\nGrade → output CST / display transform → GTap → Output\n\nAdd a separate serial node directly after the node that converts your grade into the intended display/output space. Apply GTap to that new node. Choose the matching encoded RGB declaration in Input: BT.709 or BT.2020. GTap applies no colour transform.\n\nGTap reads its own node's input; later transforms are not included. If Resolve Color Management or ACES applies the output transform after the node graph, simply putting GTap last does not make its input display-referred. Do not declare working-space or log pixels as display-encoded RGB.\n\nHOW TO CONNECT\nCopy the scopes URL into the receiving device's browser, then select Start listening. Sending is active whenever Resolve renders GTap with a declared input. Refresh status updates the viewer list. Alternate addresses are under Advanced.";[alert addButtonWithTitle:@"Close"];[alert addButtonWithTitle:@"Project website"];if([alert runModal]==NSAlertSecondButtonReturn)[[NSWorkspace sharedWorkspace] openURL:[NSURL URLWithString:@"https://vidarandersen.com/dmz/ghettoscopez"]];}}}
